#!/usr/bin/env bash
# Reproduce the real-validation numbers of 's9c' (model-lumpi-track/routed-g14) from the checkpoints: realval-A/B inference of every used
# member with its committed post-processing, bag fusion, merge with model.yaml, official metric, comparison with
# validation/results/scorecard.json. Needs the prepared real validation data and the checkpoints. Generated by
# common/tools/reproduce_validation.py. Run on an idle GPU:
#   CUDA_VISIBLE_DEVICES=0 bash model-lumpi-track/routed-g14/test/reproduce_s9c_validation.sh
# The inference commands are independent: `python common/tools/reproduce_validation.py model-lumpi-track/routed-g14 --tag s9c --jobs`
# prints them, one per line, for running several GPUs at once.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/../../.."      # the repository root (portable)
source common/env/activate.sh
mkdir -p model-lumpi-track/routed-g14/validation/output/repro_s9c
